// intent: Probes iterating over json_view array elements and dumping each.
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        std::string s = "[10, 20, 30]";
        nlohmann::json_document doc = nlohmann::json_document::parse(s);
        for (auto el : doc.root()) {
            std::cout << el.dump() << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
}
